using namespace livery;
namespace im=livery::importer;
static Bytes tinyPNG(){Image image{1,1,Bytes{255,32,16,255}};png_image png{};png.version=PNG_IMAGE_VERSION;png.width=1;png.height=1;png.format=PNG_FORMAT_RGBA;png_alloc_size_t size=0;require(png_image_write_to_memory(&png,nullptr,&size,0,image.pixels.data(),0,nullptr)!=0,"PNG size failed");Bytes encoded(size);require(png_image_write_to_memory(&png,encoded.data(),&size,0,image.pixels.data(),0,nullptr)!=0,"PNG write failed");encoded.resize(size);png_image_free(&png);return encoded;}
static Bytes fixture(Json node=Json::object(),bool badIndex=false){
 Bytes bin;for(auto p:std::vector<im::P>{{-1,0,-2},{1,0,-2},{0,1,2}})for(double x:p)im::putFloat(bin,x);for(unsigned i:{0u,1u,badIndex?8u:2u})put16(bin,i);bin.resize(44);
 auto png=tinyPNG();auto imageOffset=bin.size();bin.insert(bin.end(),png.begin(),png.end());while(bin.size()%4)bin.push_back(0);Json d={{"asset",{{"version","2.0"}}},{"buffers",Json::array({{{"byteLength",bin.size()}}})},{"bufferViews",Json::array({{{"buffer",0},{"byteOffset",0},{"byteLength",36}},{{"buffer",0},{"byteOffset",36},{"byteLength",6}},{{"buffer",0},{"byteOffset",imageOffset},{"byteLength",png.size()}}})},{"accessors",Json::array({{{"bufferView",0},{"componentType",5126},{"count",3},{"type","VEC3"}},{{"bufferView",1},{"componentType",5123},{"count",3},{"type","SCALAR"}}})},{"meshes",Json::array({{{"primitives",Json::array({{{"attributes",{{"POSITION",0}}},{"indices",1},{"material",0}}})}}})},{"scenes",Json::array({{{"nodes",Json::array({0})}}})},{"scene",0},{"images",Json::array({{{"bufferView",2},{"mimeType","image/png"}}})},{"textures",Json::array({{{"source",0}}})},{"materials",Json::array({{{"name","UpCar_M1"},{"pbrMetallicRoughness",{{"baseColorTexture",{{"index",0}}}}}}})}};node["mesh"]=0;d["nodes"]=Json::array({node});auto j=d.dump();while(j.size()%4)j+=' ';Bytes bytes;put32(bytes,0x46546c67);put32(bytes,2);put32(bytes,12+8+j.size()+8+bin.size());put32(bytes,j.size());put32(bytes,0x4e4f534a);append(bytes,j);put32(bytes,bin.size());put32(bytes,0x004e4942);bytes.insert(bytes.end(),bin.begin(),bin.end());return bytes;
}
template<class F>static void rejects(F f){bool failed=false;try{f();}catch(const std::exception&){failed=true;}require(failed,"Invalid input was accepted");}
int main(int argc,char**argv){try{
 auto basic=im::readGLB(fixture());require(basic.triangles==1&&basic.parts[0].uv.size()==3,"Basic GLB failed");require(basic.materials.size()==1&&basic.materials[0].name=="UpCar_M1"&&basic.materials[0].image==0,"GLB material or image parse failed");require(basic.images.size()==1&&basic.parts[0].materialIndex==0,"GLB primitive material failed");auto translated=im::readGLB(fixture({{"translation",{5,2,3}},{"scale",{2,1,1}}}));require(translated.parts[0].positions[0]==im::P{3,2,1},"TRS transform failed");auto mirrored=im::readGLB(fixture({{"scale",{-1,1,1}}}));require(mirrored.parts[0].indices==std::vector<uint32_t>({0,2,1}),"Mirrored winding failed");rejects([]{im::readGLB(fixture({},true));});rejects([]{im::readGLB(fixture({{"scale",{0,1,1}}}));});auto truncated=fixture();truncated.pop_back();rejects([&]{im::readGLB(truncated);});require(std::abs(half(im::toHalf(.37))-.37)<.001,"Half writer round trip failed");
 im::Source planSource;planSource.materials.push_back({"Chrome_M",0});planSource.materials.push_back({"FrontChromes_M",0});
 im::Part chrome;chrome.role=im::Metal;chrome.materialIndex=0;chrome.name="Sidechrome1_LP";
 im::Part rim;rim.role=im::Wheels;rim.materialIndex=0;rim.name="Wheel_LP";
 im::Part tyre;tyre.role=im::Wheels;tyre.materialIndex=0;tyre.name="CWheel_LP";
 im::Part interior;interior.role=im::Interior;interior.materialIndex=0;interior.name="Seat_LP";
 im::Part grille;grille.role=im::Metal;grille.materialIndex=0;grille.name="Frontchromemask_LP";
 im::Part headlight;headlight.role=im::Metal;headlight.materialIndex=0;headlight.name="BackChromelamp_LP";
 im::Part front;front.role=im::Metal;front.materialIndex=1;front.name="FrontBumper_LP";
 planSource.parts={chrome,rim,tyre,interior,grille,headlight,front};auto plan=im::defaultPlan(planSource,"dod");
 std::set<std::string> categories;for(auto &m:plan.materials)categories.insert(m.category);
 require(categories==std::set<std::string>({"wheel","chrome","interior","grille","headlight","front"}),"Automatic material categories failed");
 require(plan.partMaterial[0]>=0&&plan.partMaterial[1]>=0&&plan.partMaterial[2]==-1&&plan.partMaterial[3]>=0&&plan.partMaterial[4]>=0&&plan.partMaterial[5]>=0&&plan.partMaterial[6]>=0,"Automatic part texture binding failed");
 require(plan.materials[plan.partMaterial[1]].texture=="dod_wheel"&&plan.materials[plan.partMaterial[0]].texture=="dod_chrome"&&plan.materials[plan.partMaterial[4]].texture=="dod_grille"&&plan.materials[plan.partMaterial[5]].texture=="dod_headlight","Automatic texture names failed");
std::cout<<"Synthetic GLB transforms, bounds, indices and half-floats passed\n";
 if(argc==4){Archive archive((fs::path(argv[1])/"vfs.zip").u8string());auto source=im::readGLB(read(argv[2]));auto candidates=im::donors(archive,source.bounds.size());require(candidates.size()>=10,"Donor coverage missing");size_t passed=0;for(auto&d:candidates){try{auto result=im::convert(source,im::stockAsset(archive,"graphics/vehicles/"+d.id+"/lod0_livery.bdae"),{});require(result.report.at("imported_triangles")==source.triangles,"Lost input triangles");std::cout<<"Converted "<<d.name<<" ("<<d.id<<")\n";passed++;}catch(const std::exception&e){std::cout<<"Rejected "<<d.name<<": "<<e.what()<<"\n";}}require(passed>0,"No donor converted");auto chosen=std::find_if(candidates.begin(),candidates.end(),[](auto&d){return d.id=="alf";});require(chosen!=candidates.end(),"Missing Pulse");im::exportModel(archive,source,*chosen,{},argv[3],"Imported Impala Test");ImportedMod mod(argv[3],&archive);require(mod.cars.count("alf"),"Export did not reimport");auto labels=displayNamesFrom([&](const std::string&p){return mod.assetBytes(p,archive);});require(localized(labels,"car_alf")=="Imported Impala Test","Name export failed");ModAppearance appearance(mod,archive,labels);require(!appearance.paints.empty(),"Paint editor cannot open export");auto original=im::stockAsset(archive,"graphics/vehicles/alf/collision.hzc");require(mod.assetBytes("graphics/vehicles/alf/collision.hzc",archive)==original,"Donor collision changed");rejects([&]{im::exportModel(archive,source,*chosen,{},argv[3],"duplicate");});std::cout<<"Export, reimport, name, paint editing and no-overwrite passed; "<<passed<<" donors converted\n";
 }
 return 0;}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
